const loadedChunks = new Map();
const RADIUS = 2;

function updateStreaming(player){
 const cx = Math.floor(player.x / (32*16));
 const cy = Math.floor(player.y / (32*16));

 for(let dx=-RADIUS; dx<=RADIUS; dx++){
  for(let dy=-RADIUS; dy<=RADIUS; dy++){
   const key = `${cx+dx}_${cy+dy}`;
   if(!loadedChunks.has(key)){
    socket.emit('requestChunk',{x:cx+dx,y:cy+dy});
   }
  }
 }

 unloadFarChunks(cx,cy);
}

Unload Logic.Code:
function unloadFarChunks(cx,cy){
 loadedChunks.forEach((chunk,key)=>{
  const [x,y] = key.split('_').map(Number);
  if(Math.abs(x-cx)>2 || Math.abs(y-cy)>2){
   loadedChunks.delete(key);
   removeChunkFromScene(key);
  }
 });
}

