socket.on('requestChunk', async ({x,y})=>{
 let chunk = await db.collection('chunks').findOne({id:`${x}_${y}`});
 if(!chunk){
  chunk = generateChunk(x,y,H);
  await db.collection('chunks').insertOne(chunk);
 }
 socket.emit('chunkData',chunk);
});

Rendering Chunks (Client).Code:
socket.on('chunkData',(chunk)=>{
 loadedChunks.set(chunk.id,chunk);
 drawChunk(chunk);
});

function drawChunk(chunk){
 chunk.tiles.forEach(tile=>{
  drawTile(tile,chunk.id);
 });
}

Render Logic.Code:
function drawMinimap(player){
 mctx.clearRect(0,0,200,200);

 loadedChunks.forEach((chunk,key)=>{
  const [x,y] = key.split('_').map(Number);
  let color = 'green';

  if(chunk.biome==='desert') color='yellow';
  if(chunk.biome==='forest') color='darkgreen';
  if(chunk.biome==='warzone') color='red';

  mctx.fillStyle = color;
  mctx.fillRect(100 + x*5, 100 + y*5, 5, 5);
 });

 // Player marker
 mctx.fillStyle='blue';
 mctx.fillRect(100,100,4,4);
}

